proguardAdditions.insert:

-keep class com.taptap.sdk.moment.** { *; }
-keep interface com.taptap.sdk.moment.** { *; }
-keep class com.taptap.sdk.moment.unity.** { *; }
-keepclassmembers class com.taptap.sdk.moment.unity.** { *; }
-keepclasseswithmembernames class * { native <methods>; }

gameActivityClassAdditions.insert:

private BridgeMomentServiceImpl mMomentService;

private BridgeMomentServiceImpl getMomentService() {
    if (mMomentService == null) { mMomentService = new BridgeMomentServiceImpl(); }
    return mMomentService;
}

public void routeToTapMoment(String requestJson, EngineBridgeCallback callback) {
    try {
        org.json.JSONObject req = new org.json.JSONObject(requestJson);
        String method  = req.getString("method");
        String argsStr = req.optString("args", "");
        switch (method) {
            case "openMoment":
                getMomentService().openMoment();
                break;
            case "openScene":
                getMomentService().openScene(
                    new org.json.JSONObject(argsStr).getString("sceneId"));
                break;
            case "close":
                getMomentService().close();
                break;
            case "closeWithConfirmWindow": {
                org.json.JSONObject a = new org.json.JSONObject(argsStr);
                getMomentService().closeWithConfirmWindow(
                    a.optString("title"), a.optString("content"));
                break;
            }
            case "fetchNotification":
                getMomentService().fetchNotification();
                break;
            case "publish":
                getMomentService().publish(
                    new org.json.JSONObject(argsStr).getString("publishMetaData"));
                break;
            case "setCallback":
                getMomentService().setCallback(callback);
                break;
            default:
                android.util.Log.w("TapSDK_UE", "TapMoment: unknown method: " + method);
        }
    } catch (Exception e) {
        android.util.Log.e("TapSDK_UE", "TapMoment route error: " + e.getMessage(), e);
    }
}
